import java.util.*;
class SharedTotal {long total;void add(long n){total+=n;}synchronized void safeAdd(long n){total+=n;}}
public class Main {public static void main(String[] args)throws Exception{Scanner sc=new Scanner(System.in);System.out.print("Array size: ");int size=sc.nextInt();System.out.print("Threads: ");int n=sc.nextInt();int[] a=new int[size];long correct=0;for(int i=0;i<size;i++){a[i]=i%10+1;correct+=a[i];}for(boolean safe:new boolean[]{false,true}){SharedTotal total=new SharedTotal();Thread[] ts=new Thread[n];long start=System.nanoTime();for(int t=0;t<n;t++){final int lo=t*size/n,hi=(t+1)*size/n;ts[t]=new Thread(()->{for(int i=lo;i<hi;i++)if(safe)total.safeAdd(a[i]);else total.add(a[i]);});}for(Thread t:ts)t.start();for(Thread t:ts)t.join();System.out.println((safe?"Synchronized":"Unsynchronized")+" total="+total.total+" expected="+correct+" time="+(System.nanoTime()-start)+" ns");}sc.close();}}
